{
  "implementation": "def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    accepted = []
    diagnostics = []
    for call in calls:
        call_id = call['call_id']
        gain = call['loss_without_call'] - call['loss_with_call']
        norm_gain = gain / max(1, call['prediction_tokens'])
        rounded_gain = round(norm_gain, 6)
        accepted_flag = call['parseable'] and rounded_gain >= threshold
        diagnostics.append({
            'accepted': accepted_flag,
            'call_id': call_id,
            'normalized_gain': rounded_gain
        })
        if accepted_flag:
            accepted.append(call_id)
    return {
        'accepted_call_ids': accepted,
        'diagnostics': diagnostics
    }"
}
